// 配置热更新：配置中心推送变更时，运行中实例无需重启即可生效
class ConfigStore {
  constructor(initial) {
    this.data = { ...initial };
    this.listeners = new Set();
  }
  get(key) { return this.data[key]; }
  subscribe(fn) { this.listeners.add(fn); return () => this.listeners.delete(fn); }
  update(patch) {
    this.data = { ...this.data, ...patch };
    for (const fn of this.listeners) fn(this.data);
  }
}

const cs = new ConfigStore({ featureX: false, rate: 10 });
const unsub = cs.subscribe((d) => console.log("热更新:", JSON.stringify(d)));
console.log("初始:", cs.get("featureX"));
cs.update({ featureX: true }); // 推送到订阅者，无需重启
cs.update({ rate: 20 });
unsub();
cs.update({ featureX: false }); // 已退订，不再输出
console.log("最终:", cs.get("featureX"));
